import{_ as s,C as o,o as r,c as i,j as n,a,E as l,a2 as d}from"./chunks/framework.DQbsdZKN.js";const y=JSON.parse('{"title":"Engine Blindness Challenges","description":"Every place the Frensense engine is silent or wrong on real code, as a challenge anyone can fix and earn credit for.","frontmatter":{"title":"Engine Blindness Challenges","description":"Every place the Frensense engine is silent or wrong on real code, as a challenge anyone can fix and earn credit for."},"headers":[],"relativePath":"challenges.md","filePath":"challenges.md"}'),h={name:"challenges.md"};function c(g,e,p,u,b,m){const t=o("BlindnessChallenges");return r(),i("div",null,[e[0]||(e[0]=n("h1",{id:"engine-blindness-challenges",tabindex:"-1"},[a("Engine Blindness Challenges "),n("a",{class:"header-anchor",href:"#engine-blindness-challenges","aria-label":'Permalink to "Engine Blindness Challenges"'},"​")],-1)),e[1]||(e[1]=n("p",null,[a("Each run of the "),n("strong",null,"engine blindness"),a(" CI scans pinned real codebases and labelled vulnerable suites. Wherever the engine loses a value, misses a known bug, or raises a false alarm, that spot becomes a challenge here. Fix the engine, and the challenge drops off the board on the next run. Your merged fix earns points and badges.")],-1)),l(t),e[2]||(e[2]=d('<h2 id="how-to-take-one" tabindex="-1">How to take one <a class="header-anchor" href="#how-to-take-one" aria-label="Permalink to &quot;How to take one&quot;">​</a></h2><ol><li><p><strong>Pick</strong> a challenge and open it. Run the command under <em>Where to start</em> against the pinned repo: it lists every sink the engine explored and where each walk stopped.</p></li><li><p><strong>Fix the engine.</strong> The <a href="/architecture/blindness">blindness page</a> explains the verdicts and where fixes usually go.</p></li><li><p><strong>Claim it.</strong> Press <em>Copy claim line</em> and paste it into your pull request description:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Solves: BG-0123456789</span></span></code></pre></div><p>You can claim up to 10 challenges per pull request.</p></li><li><p><strong>Watch the check.</strong> CI rescans the repos your challenges belong to with your branch and comments with what changed. It also fails if your change adds open challenges, loses a detection, or adds a false alarm in a repo it scanned: a fix must not trade one blind spot for another.</p></li><li><p><strong>Merge.</strong> After the merge, the <code>main</code> run scans again. Every sink of a claimed challenge that is now gone earns you credit, and you appear on the leaderboard.</p></li></ol><p>Credit is decided by the scan of <code>main</code>, never by the pull request check, so it reflects what actually shipped.</p><h2 id="points-and-badges" tabindex="-1">Points and badges <a class="header-anchor" href="#points-and-badges" aria-label="Permalink to &quot;Points and badges&quot;">​</a></h2><p>A challenge is worth <strong>2</strong> points (easy), <strong>4</strong> (medium) or <strong>8</strong> (hard), multiplied by <code>1 + log2(sinks you removed)</code>, plus the same amount again when you take it all the way to zero. A 300-sink challenge is not worth 300 small ones: the hard part is the first fix, and partial progress still counts.</p><table tabindex="0"><thead><tr><th>Badge</th><th>How to earn it</th></tr></thead><tbody><tr><td>First Light</td><td>Your first merged fix</td></tr><tr><td>Sharp Eye</td><td>Remove 10 blind spots</td></tr><tr><td>Clean Sweep</td><td>Take 3 challenges to zero</td></tr><tr><td>Deep Diver</td><td>Clear a hard challenge</td></tr><tr><td>Polyglot</td><td>Fix the engine in 3 languages</td></tr><tr><td><strong>Core Contributor</strong></td><td>5 merged fixes and 50 points</td></tr></tbody></table><p>Thresholds live in <a href="https://github.com/Friehub/Frensense-v2/blob/main/frensense-bench/badges.json" target="_blank" rel="noreferrer"><code>frensense-bench/badges.json</code></a> and badges are recomputed from the ledger on every run, so they never drift.</p><h2 id="the-scoreboard" tabindex="-1">The Scoreboard <a class="header-anchor" href="#the-scoreboard" aria-label="Permalink to &quot;The Scoreboard&quot;">​</a></h2><p>The Scoreboard tab shows how the engine does on suites where the answer is known, such as OWASP BenchmarkPython: bugs found, bugs missed, false alarms, and cases it correctly left alone, per vulnerability category. The score is recall minus false-positive rate, the OWASP Benchmark&#39;s own measure, so a fix that finds more bugs by raising more false alarms does not move it.</p><p>Looking for the commit-by-commit blindness rate? See <a href="/architecture/blindness">Engine blindness &amp; capabilities</a>.</p>',10))])}const k=s(h,[["render",c]]);export{y as __pageData,k as default};
